insert into public.proyectos_ideas (id, area, areas2, titulo, resumen, tipo, tiempo, horas, etiquetas, intencion, datos, prog, busca, ficha, orden) values
('analizando-la-comunicacion-dentro-de-una-comunidad','sociedad',array['tecnologia']::text[],'Analizando la comunicación dentro de una comunidad','Observa cómo se comunica una comunidad, por qué canales, quién habla, quién queda fuera y qué información se pierde, para entender qué funciona y qué no.','Análisis','3 semanas',22,array['Comunicación','Comunidad']::text[],array['investigar']::text[],'propios',NULL,'trabajo social sociologia ingenieria de sistemas estadistica comunicaciones educacion ingenieria industrial administracion analisis de comunicacion. diseno de encuestas. diagramas. redaccion. un formulario en linea. un editor de diagramas. una guia de observacion.',$a25sld${"id": "analizando-la-comunicacion-dentro-de-una-comunidad", "area": "sociedad", "areas2": ["tecnologia"], "titulo": "Analizando la comunicación dentro de una comunidad", "resumen": "Observa cómo se comunica una comunidad, por qué canales, quién habla, quién queda fuera y qué información se pierde, para entender qué funciona y qué no.", "tipo": "Análisis", "tiempo": "3 semanas", "horas": 22, "etiquetas": ["Comunicación", "Comunidad"], "intencion": ["investigar"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Trabajo Social", "Sociología", "Ingeniería de Sistemas", "Estadística", "Comunicaciones", "Educación", "Ingeniería Industrial", "Administración"], "problema": ["Las comunidades se comunican por carteles, reuniones, chats, voz a voz y redes sociales, pero no todos acceden a todos los canales. La información llega a algunos y a otros no, y se generan malentendidos o rumores.", "Analizar la comunicación permite mejorar cómo circula lo importante."], "desarrollar": ["Elige una comunidad, como un barrio, un salón o un grupo, y mapea los canales de comunicación que usa. Con una encuesta anónima, pregunta por dónde se enteran de lo importante, qué se les pasa y qué entienden mal.", "Dibuja el mapa de canales, identifica los puntos donde la información se pierde y propone tres cambios sencillos, como un resumen semanal o un tablero físico. Presenta los resultados en un informe corto."], "ampliaciones": [{"titulo": "Rumores", "aporta": "traza cómo se propaga una información incorrecta."}, {"titulo": "Quién queda fuera", "aporta": "identifica qué grupos no acceden a los canales."}, {"titulo": "Prueba de mejora", "aporta": "aplica un cambio y mide si mejora el acceso."}], "objetivos": ["Mapear canales.", "Detectar pérdidas de información.", "Proponer cambios.", "Presentar un informe."], "habilidades": ["Análisis de comunicación.", "Diseño de encuestas.", "Diagramas.", "Redacción."], "herramientas": ["Un formulario en línea.", "Un editor de diagramas.", "Una guía de observación."], "lineamientos": ["Si entrevistas o encuestas a personas, que sea voluntario, anónimo y con consentimiento claro, sin recoger datos personales ni imágenes sin permiso.", "Trabaja con la comunidad y no sobre ella: devuelve los resultados a quienes participaron y evita presentar a un grupo como problema.", "No registres el contenido de chats privados: analiza solo canales y no conversaciones."], "otroSector": "El mismo análisis sirve para la comunicación interna en una empresa o institución."}$a25sld$::jsonb,35),
('disenando-acuerdos-para-mejorar-la-convivencia-grupal-y-la-colab','sociedad',array['educacion']::text[],'Diseñando acuerdos para mejorar la convivencia grupal y la colaboración entre estudiantes','Diseña una guía y una plantilla de acuerdos de convivencia y colaboración para grupos de estudiantes, con una dinámica para elaborarlos en conjunto y revisarlos a lo largo del tiempo.','Prototipo','3 semanas',24,array['Acuerdos','Colaboración']::text[],array['crear']::text[],'ficticios',NULL,'trabajo social sociologia psicologia educacion comunicaciones antropologia ciencias politicas administracion facilitacion. diseno de dinamicas. redaccion de acuerdos. comunicacion. un editor de documentos. papelografo o pizarra. un grupo voluntario.',$a26sld${"id": "disenando-acuerdos-para-mejorar-la-convivencia-grupal-y-la-colab", "area": "sociedad", "areas2": ["educacion"], "titulo": "Diseñando acuerdos para mejorar la convivencia grupal y la colaboración entre estudiantes", "resumen": "Diseña una guía y una plantilla de acuerdos de convivencia y colaboración para grupos de estudiantes, con una dinámica para elaborarlos en conjunto y revisarlos a lo largo del tiempo.", "tipo": "Prototipo", "tiempo": "3 semanas", "horas": 24, "etiquetas": ["Acuerdos", "Colaboración"], "intencion": ["crear"], "datos": "ficticios", "datosTexto": "ficticios: trabaja con casos inventados o simulados; no hace falta pedir permiso a nadie ni usar información real de otras personas.", "carreras": ["Trabajo Social", "Sociología", "Psicología", "Educación", "Comunicaciones", "Antropología", "Ciencias Políticas", "Administración"], "problema": ["Los acuerdos de convivencia suelen imponerse o improvisarse, y por eso no se cumplen. Cuando el grupo no participa en armarlos, no los siente suyos y se rompen apenas aparece una tensión.", "Una forma participativa de construirlos aumenta el compromiso y la confianza."], "desarrollar": ["Diseña una dinámica de 45 minutos para que un grupo defina sus acuerdos, con preguntas como qué necesitamos para trabajar bien, qué nos molestaría y qué haremos si alguien no cumple. Elabora una plantilla de una página.", "Prueba la dinámica con un grupo de compañeros, recoge su opinión y ajusta. Agrega una forma de revisar los acuerdos a mitad del trabajo y de reconocer lo que sí funciona."], "ampliaciones": [{"titulo": "Acuerdos digitales", "aporta": "adáptalos para un grupo que se coordina por chat."}, {"titulo": "Consecuencias constructivas", "aporta": "define cómo se actúa ante incumplimientos sin humillar."}, {"titulo": "Revisión", "aporta": "diseña un chequeo de cinco minutos cada semana."}], "objetivos": ["Diseñar una dinámica participativa.", "Elaborar una plantilla.", "Probarla con un grupo.", "Mejorarla."], "habilidades": ["Facilitación.", "Diseño de dinámicas.", "Redacción de acuerdos.", "Comunicación."], "herramientas": ["Un editor de documentos.", "Papelógrafo o pizarra.", "Un grupo voluntario."], "lineamientos": ["Trabaja con la comunidad y no sobre ella: devuelve los resultados a quienes participaron y evita presentar a un grupo como problema.", "No recojas datos personales de otras personas: usa códigos o promedios, pide permiso para cualquier prueba y respeta quién prefiere no participar.", "Trabaja con un grupo ficticio o con permiso de los participantes."], "otroSector": "La misma plantilla sirve para acuerdos de trabajo en equipos o de uso de espacios compartidos."}$a26sld$::jsonb,36),
('como-se-construye-la-confianza-dentro-de-un-grupo-y-que-hace-que','sociedad',array['educacion']::text[],'¿Cómo se construye la confianza dentro de un grupo y qué hace que una comunidad confíe o desconfíe de las iniciativas colectivas?','Estudia qué prácticas aumentan la confianza dentro de un grupo y qué experiencias hacen que una comunidad desconfíe de proyectos colectivos, a partir de conversaciones voluntarias y anónimas.','Investigación','3 a 4 semanas',24,array['Confianza','Iniciativas colectivas']::text[],array['investigar']::text[],'propios',NULL,'trabajo social sociologia psicologia educacion comunicaciones antropologia ciencias politicas administracion entrevistas. analisis cualitativo. sintesis. redaccion. un formulario en linea. una guia de conversacion. un editor de documentos.',$a27sld${"id": "como-se-construye-la-confianza-dentro-de-un-grupo-y-que-hace-que", "area": "sociedad", "areas2": ["educacion"], "titulo": "¿Cómo se construye la confianza dentro de un grupo y qué hace que una comunidad confíe o desconfíe de las iniciativas colectivas?", "resumen": "Estudia qué prácticas aumentan la confianza dentro de un grupo y qué experiencias hacen que una comunidad desconfíe de proyectos colectivos, a partir de conversaciones voluntarias y anónimas.", "tipo": "Investigación", "tiempo": "3 a 4 semanas", "horas": 24, "etiquetas": ["Confianza", "Iniciativas colectivas"], "intencion": ["investigar"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Trabajo Social", "Sociología", "Psicología", "Educación", "Comunicaciones", "Antropología", "Ciencias Políticas", "Administración"], "problema": ["La confianza se construye lentamente y se rompe rápido. Una colecta sin cuentas claras o promesas incumplidas pueden hacer que una comunidad no vuelva a participar. Por eso, lo que se hace y cómo se informa pesa tanto como lo que se propone.", "Entender qué genera confianza permite organizar mejor iniciativas colectivas."], "desarrollar": ["Con una encuesta breve y cinco a ocho conversaciones voluntarias, pregunta qué experiencias han fortalecido o dañado su confianza en grupos o iniciativas y qué señales buscan, como transparencia, cumplimiento o trato.", "Agrupa las respuestas en factores y elabora una lista de prácticas, como rendir cuentas, cumplir plazos, escuchar y compartir decisiones. Convierte la lista en una guía breve para quienes organizan iniciativas."], "ampliaciones": [{"titulo": "Primera impresión", "aporta": "analiza qué pasa en las primeras reuniones."}, {"titulo": "Recuperar la confianza", "aporta": "estudia qué ayuda tras una mala experiencia."}, {"titulo": "Rendición de cuentas", "aporta": "diseña un formato sencillo de rendición de cuentas."}], "objetivos": ["Recoger experiencias.", "Identificar factores de confianza.", "Elaborar una guía.", "Compartirla."], "habilidades": ["Entrevistas.", "Análisis cualitativo.", "Síntesis.", "Redacción."], "herramientas": ["Un formulario en línea.", "Una guía de conversación.", "Un editor de documentos."], "lineamientos": ["Si entrevistas o encuestas a personas, que sea voluntario, anónimo y con consentimiento claro, sin recoger datos personales ni imágenes sin permiso.", "Trabaja con la comunidad y no sobre ella: devuelve los resultados a quienes participaron y evita presentar a un grupo como problema.", "No menciones iniciativas ni personas reales con nombre en tu análisis."], "otroSector": "El mismo estudio sirve para entender la confianza en equipos de trabajo y en marcas."}$a27sld$::jsonb,37),
('que-ocurre-cuando-una-persona-se-siente-excluida-de-un-grupo','sociedad',array['salud']::text[],'¿Qué ocurre cuando una persona se siente excluida de un grupo?','Revisa lo que se sabe sobre cómo afecta sentirse excluido de un grupo, qué formas de exclusión existen y qué prácticas ayudan a que nadie quede al margen, con un enfoque respetuoso.','Investigación','3 semanas',22,array['Exclusión','Pertenencia']::text[],array['investigar']::text[],'publicos',NULL,'trabajo social sociologia psicologia educacion comunicaciones antropologia ciencias politicas administracion lectura de fuentes. empatia. diseno de materiales. redaccion. fuentes confiables. un editor de documentos. casos ficticios.',$a28sld${"id": "que-ocurre-cuando-una-persona-se-siente-excluida-de-un-grupo", "area": "sociedad", "areas2": ["salud"], "titulo": "¿Qué ocurre cuando una persona se siente excluida de un grupo?", "resumen": "Revisa lo que se sabe sobre cómo afecta sentirse excluido de un grupo, qué formas de exclusión existen y qué prácticas ayudan a que nadie quede al margen, con un enfoque respetuoso.", "tipo": "Investigación", "tiempo": "3 semanas", "horas": 22, "etiquetas": ["Exclusión", "Pertenencia"], "intencion": ["investigar"], "datos": "publicos", "datosTexto": "públicos: trabaja con informes, estadísticas y registros que publican instituciones y fuentes abiertas.", "carreras": ["Trabajo Social", "Sociología", "Psicología", "Educación", "Comunicaciones", "Antropología", "Ciencias Políticas", "Administración"], "problema": ["Sentirse fuera de un grupo de estudio, de un salón o de una comunidad puede afectar el ánimo, el rendimiento y las ganas de participar. A veces la exclusión no es explícita: son pequeños gestos que no se notan desde fuera.", "Entender cómo ocurre ayuda a evitarla sin señalar a nadie."], "desarrollar": ["Con fuentes confiables, resume qué se sabe sobre los efectos de la exclusión y cuáles son sus formas más comunes, como ignorar, no invitar o no escuchar. Presenta tres a cinco casos ficticios y explica qué señales aparecen.", "Diseña una lista de prácticas para incluir, como rotar roles, preguntar la opinión de todos o cuidar el lenguaje, y un material breve para grupos estudiantiles."], "ampliaciones": [{"titulo": "Cómo acercarse a alguien", "aporta": "elabora una guía de gestos de inclusión."}, {"titulo": "Grupos de trabajo", "aporta": "adapta las prácticas a equipos de proyectos."}, {"titulo": "Espacios en línea", "aporta": "analiza la exclusión en chats y redes."}], "objetivos": ["Revisar fuentes sobre exclusión.", "Describir formas y señales.", "Diseñar prácticas de inclusión.", "Elaborar un material."], "habilidades": ["Lectura de fuentes.", "Empatía.", "Diseño de materiales.", "Redacción."], "herramientas": ["Fuentes confiables.", "Un editor de documentos.", "Casos ficticios."], "lineamientos": ["Trata el tema con respeto: usa casos inventados o anónimos, sin datos que identifiquen a nadie, y si alguien necesita ayuda urgente remítelo a los servicios oficiales de atención, sin dar consejos psicológicos ni legales.", "Cita las fuentes que uses para respaldar lo que afirmas sobre cómo se aprende, y distingue entre lo que muestra la evidencia y lo que es tu opinión.", "No uses casos reales ni señales a personas concretas."], "otroSector": "El mismo material sirve para fomentar la inclusión en equipos de trabajo y clubes."}$a28sld$::jsonb,38),
('como-influyen-los-prejuicios-en-la-forma-en-que-tratamos-a-perso','sociedad',array['educacion']::text[],'¿Cómo influyen los prejuicios en la forma en que tratamos a personas diferentes a nosotros?','Estudia qué son los prejuicios, cómo se forman y cómo influyen en el trato cotidiano, y diseña una actividad para reflexionar sin señalar ni avergonzar a nadie.','Investigación','3 semanas',22,array['Prejuicios','Trato']::text[],array['investigar','crear']::text[],'publicos',NULL,'trabajo social sociologia psicologia educacion comunicaciones antropologia ciencias politicas administracion lectura critica. facilitacion. empatia. diseno de actividades. fuentes academicas. un editor de documentos. un grupo voluntario.',$a29sld${"id": "como-influyen-los-prejuicios-en-la-forma-en-que-tratamos-a-perso", "area": "sociedad", "areas2": ["educacion"], "titulo": "¿Cómo influyen los prejuicios en la forma en que tratamos a personas diferentes a nosotros?", "resumen": "Estudia qué son los prejuicios, cómo se forman y cómo influyen en el trato cotidiano, y diseña una actividad para reflexionar sin señalar ni avergonzar a nadie.", "tipo": "Investigación", "tiempo": "3 semanas", "horas": 22, "etiquetas": ["Prejuicios", "Trato"], "intencion": ["investigar", "crear"], "datos": "publicos", "datosTexto": "públicos: trabaja con informes, estadísticas y registros que publican instituciones y fuentes abiertas.", "carreras": ["Trabajo Social", "Sociología", "Psicología", "Educación", "Comunicaciones", "Antropología", "Ciencias Políticas", "Administración"], "problema": ["Los prejuicios son ideas previas sobre grupos de personas que se asumen como ciertas sin conocerlas. A veces se expresan en chistes, en gestos o en decisiones, y quien los tiene muchas veces no lo nota.", "Entender cómo funcionan ayuda a reconocerlos y a cambiar conductas."], "desarrollar": ["Con fuentes académicas y de divulgación, resume qué son los prejuicios, estereotipos y discriminación, y cómo se diferencian. Reúne ejemplos cotidianos, en abstracto, de cómo influyen en el trato.", "Diseña una actividad corta, como un juego de preguntas o una reflexión escrita anónima, para que un grupo reconozca ideas previas sin sentirse evaluado. Pruébala con compañeros y ajusta el tono."], "ampliaciones": [{"titulo": "Cuestionar suposiciones", "aporta": "diseña preguntas que ayuden a revisar ideas previas."}, {"titulo": "Lenguaje", "aporta": "analiza cómo el lenguaje refuerza estereotipos."}, {"titulo": "Contacto entre grupos", "aporta": "revisa qué dice la evidencia sobre el contacto positivo."}], "objetivos": ["Distinguir prejuicio, estereotipo y discriminación.", "Reunir ejemplos cotidianos.", "Diseñar una actividad reflexiva.", "Probarla."], "habilidades": ["Lectura crítica.", "Facilitación.", "Empatía.", "Diseño de actividades."], "herramientas": ["Fuentes académicas.", "Un editor de documentos.", "Un grupo voluntario."], "lineamientos": ["Trata el tema con respeto: usa casos inventados o anónimos, sin datos que identifiquen a nadie, y si alguien necesita ayuda urgente remítelo a los servicios oficiales de atención, sin dar consejos psicológicos ni legales.", "Cita las fuentes que uses para respaldar lo que afirmas sobre cómo se aprende, y distingue entre lo que muestra la evidencia y lo que es tu opinión.", "Evita reproducir estereotipos en tus ejemplos y no expongas a ningún participante."], "otroSector": "La misma actividad sirve para talleres de diversidad en empresas."}$a29sld$::jsonb,39),
('analizando-percepciones-sobre-el-trato-respetuoso','sociedad',array[]::text[],'Analizando percepciones sobre el trato respetuoso','Averigua con una encuesta anónima qué entienden distintas personas por trato respetuoso y qué conductas consideran faltas de respeto, para ver dónde coinciden y dónde difieren.','Investigación','3 semanas',20,array['Respeto','Percepciones']::text[],array['investigar']::text[],'propios',NULL,'trabajo social sociologia psicologia educacion comunicaciones antropologia ciencias politicas administracion diseno de encuestas. analisis de datos. redaccion. comunicacion. un formulario en linea. hoja de calculo. un editor de graficos.',$a30sld${"id": "analizando-percepciones-sobre-el-trato-respetuoso", "area": "sociedad", "areas2": [], "titulo": "Analizando percepciones sobre el trato respetuoso", "resumen": "Averigua con una encuesta anónima qué entienden distintas personas por trato respetuoso y qué conductas consideran faltas de respeto, para ver dónde coinciden y dónde difieren.", "tipo": "Investigación", "tiempo": "3 semanas", "horas": 20, "etiquetas": ["Respeto", "Percepciones"], "intencion": ["investigar"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Trabajo Social", "Sociología", "Psicología", "Educación", "Comunicaciones", "Antropología", "Ciencias Políticas", "Administración"], "problema": ["Lo que para unos es una broma, para otros es una falta de respeto. Esas diferencias de percepción generan conflictos aun cuando nadie tuvo mala intención.", "Conocerlas permite acordar normas que todos entiendan."], "desarrollar": ["Diseña una encuesta anónima con situaciones breves, como una broma, interrumpir o un apodo, y pide calificar qué tan respetuosas o no las consideran. Aplícala a 30 o más personas de un entorno con consentimiento.", "Compara las respuestas por grupos, identifica situaciones con alto acuerdo y con alto desacuerdo, y propón cinco acuerdos básicos de trato para el grupo."], "ampliaciones": [{"titulo": "Contexto", "aporta": "analiza si la percepción cambia según el lugar o la confianza."}, {"titulo": "En línea y en persona", "aporta": "compara el trato en chats y cara a cara."}, {"titulo": "Cartel de acuerdos", "aporta": "diseña un material visual con los acuerdos."}], "objetivos": ["Diseñar una encuesta de situaciones.", "Comparar percepciones.", "Identificar acuerdos y desacuerdos.", "Proponer normas."], "habilidades": ["Diseño de encuestas.", "Análisis de datos.", "Redacción.", "Comunicación."], "herramientas": ["Un formulario en línea.", "Hoja de cálculo.", "Un editor de gráficos."], "lineamientos": ["Si entrevistas o encuestas a personas, que sea voluntario, anónimo y con consentimiento claro, sin recoger datos personales ni imágenes sin permiso.", "Es un estudio pequeño con pocas personas o contigo mismo: no pretendas sacar conclusiones generales, solo patrones que te ayuden a decidir.", "Usa situaciones genéricas y evita casos que identifiquen a personas."], "otroSector": "La misma encuesta sirve para definir normas de trato en equipos y empresas."}$a30sld$::jsonb,40),
('como-promover-una-cultura-de-respeto-mutuo-una-propuesta-para-me','sociedad',array['educacion']::text[],'¿Cómo promover una cultura de respeto mutuo? Una propuesta para mejorar la convivencia respetuosa','Diseña una propuesta para promover el respeto mutuo en un grupo o institución, con acciones concretas, responsables, calendario y formas de saber si algo cambia.','Plan','4 semanas',26,array['Cultura de respeto','Convivencia']::text[],array['crear']::text[],'ficticios',NULL,'trabajo social sociologia psicologia educacion comunicaciones antropologia ciencias politicas administracion diseno de proyectos. planificacion. indicadores. redaccion. un editor de documentos. hoja de calculo. un editor de presentaciones.',$a31sld${"id": "como-promover-una-cultura-de-respeto-mutuo-una-propuesta-para-me", "area": "sociedad", "areas2": ["educacion"], "titulo": "¿Cómo promover una cultura de respeto mutuo? Una propuesta para mejorar la convivencia respetuosa", "resumen": "Diseña una propuesta para promover el respeto mutuo en un grupo o institución, con acciones concretas, responsables, calendario y formas de saber si algo cambia.", "tipo": "Plan", "tiempo": "4 semanas", "horas": 26, "etiquetas": ["Cultura de respeto", "Convivencia"], "intencion": ["crear"], "datos": "ficticios", "datosTexto": "ficticios: trabaja con casos inventados o simulados; no hace falta pedir permiso a nadie ni usar información real de otras personas.", "carreras": ["Trabajo Social", "Sociología", "Psicología", "Educación", "Comunicaciones", "Antropología", "Ciencias Políticas", "Administración"], "problema": ["El respeto no se logra con carteles ni con normas escritas solamente: se construye con prácticas cotidianas, ejemplos y espacios de diálogo. Muchas campañas de convivencia se quedan en lemas.", "Una propuesta con acciones medibles es más probable que genere cambios."], "desarrollar": ["Elige un entorno, como una facultad, un colegio o un barrio, define un problema de convivencia y diseña cinco a seis acciones concretas, como talleres, acuerdos, reconocimiento de buenas prácticas y canales para conversar. Asigna responsables y fechas.", "Define tres indicadores para ver si hay cambios, como percepción de respeto o cantidad de conflictos, y prepara la propuesta en un documento de dos a tres páginas."], "ampliaciones": [{"titulo": "Costos y recursos", "aporta": "estima qué haría falta para ejecutar la propuesta."}, {"titulo": "Voces involucradas", "aporta": "define cómo incluir a distintos grupos en el diseño."}, {"titulo": "Evaluación", "aporta": "diseña una encuesta de entrada y de salida."}], "objetivos": ["Definir un problema de convivencia.", "Diseñar acciones.", "Definir indicadores.", "Redactar la propuesta."], "habilidades": ["Diseño de proyectos.", "Planificación.", "Indicadores.", "Redacción."], "herramientas": ["Un editor de documentos.", "Hoja de cálculo.", "Un editor de presentaciones."], "lineamientos": ["Trabaja con la comunidad y no sobre ella: devuelve los resultados a quienes participaron y evita presentar a un grupo como problema.", "Preséntala como propuesta: para ejecutarla se necesita acuerdo de la institución.", "No recojas datos personales de otras personas: usa códigos o promedios, pide permiso para cualquier prueba y respeta quién prefiere no participar."], "otroSector": "La misma propuesta sirve para mejorar el clima laboral en una organización."}$a31sld$::jsonb,41),
('identificando-acciones-que-fortalecen-la-inclusion-y-el-respeto','sociedad',array['educacion']::text[],'Identificando acciones que fortalecen la inclusión y el respeto por las diferencias culturales','Reúne acciones concretas que ayudan a que todas las personas se sientan incluidas en un grupo o comunidad, y las organiza en una guía para fomentar el respeto por las diferencias culturales.','Guía','3 a 4 semanas',22,array['Inclusión','Diferencias culturales']::text[],array['investigar','crear']::text[],'propios',NULL,'trabajo social sociologia psicologia educacion comunicaciones antropologia ciencias politicas administracion investigacion. sintesis. diseno de guias. sensibilidad intercultural. fuentes confiables. un editor de infografias. un editor de documentos.',$a32sld${"id": "identificando-acciones-que-fortalecen-la-inclusion-y-el-respeto", "area": "sociedad", "areas2": ["educacion"], "titulo": "Identificando acciones que fortalecen la inclusión y el respeto por las diferencias culturales", "resumen": "Reúne acciones concretas que ayudan a que todas las personas se sientan incluidas en un grupo o comunidad, y las organiza en una guía para fomentar el respeto por las diferencias culturales.", "tipo": "Guía", "tiempo": "3 a 4 semanas", "horas": 22, "etiquetas": ["Inclusión", "Diferencias culturales"], "intencion": ["investigar", "crear"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Trabajo Social", "Sociología", "Psicología", "Educación", "Comunicaciones", "Antropología", "Ciencias Políticas", "Administración"], "problema": ["La inclusión no ocurre por decreto: depende de acciones cotidianas, como invitar, escuchar, adaptar actividades y reconocer costumbres distintas. Muchas comunidades no saben por dónde empezar.", "Una guía de acciones concretas ayuda a pasar de las buenas intenciones a la práctica."], "desarrollar": ["Reúne 15 a 20 acciones de inclusión de fuentes confiables y de experiencias de grupos de tu entorno, con permiso. Clasifícalas por ámbito: invitación, comunicación, actividades y espacios.", "Selecciona las diez más viables, escribe cómo se implementan, qué recursos requieren y qué dificultades tienen, y arma una guía visual con ejemplos para estudiantes o vecinos."], "ampliaciones": [{"titulo": "Calendario cultural", "aporta": "propón un calendario de celebraciones de distintas culturas."}, {"titulo": "Auditoría de inclusión", "aporta": "crea una lista para revisar si un grupo es inclusivo."}, {"titulo": "Voces de la comunidad", "aporta": "recoge qué acciones valoran más las personas."}], "objetivos": ["Reunir acciones de inclusión.", "Clasificarlas.", "Seleccionar las más viables.", "Elaborar una guía."], "habilidades": ["Investigación.", "Síntesis.", "Diseño de guías.", "Sensibilidad intercultural."], "herramientas": ["Fuentes confiables.", "Un editor de infografías.", "Un editor de documentos."], "lineamientos": ["Trabaja con la comunidad y no sobre ella: devuelve los resultados a quienes participaron y evita presentar a un grupo como problema.", "Si entrevistas o encuestas a personas, que sea voluntario, anónimo y con consentimiento claro, sin recoger datos personales ni imágenes sin permiso.", "Evita presentar a una cultura como un estereotipo y cita las experiencias que uses."], "otroSector": "La misma guía sirve para programas de diversidad en empresas o clubes."}$a32sld$::jsonb,42),
('que-tan-representadas-se-sienten-las-distintas-voces-en-las-deci','sociedad',array['derecho']::text[],'¿Qué tan representadas se sienten las distintas voces en las decisiones de un grupo?','Mide qué tan escuchadas se sienten distintas personas de un grupo cuando se toman decisiones, y descubre qué voces pesan más y cuáles quedan fuera.','Investigación','3 semanas',22,array['Representación','Decisiones']::text[],array['investigar']::text[],'propios',NULL,'trabajo social sociologia psicologia educacion comunicaciones antropologia ciencias politicas administracion diseno de encuestas. observacion. analisis. facilitacion. un formulario en linea. una guia de observacion. hoja de calculo.',$a33sld${"id": "que-tan-representadas-se-sienten-las-distintas-voces-en-las-deci", "area": "sociedad", "areas2": ["derecho"], "titulo": "¿Qué tan representadas se sienten las distintas voces en las decisiones de un grupo?", "resumen": "Mide qué tan escuchadas se sienten distintas personas de un grupo cuando se toman decisiones, y descubre qué voces pesan más y cuáles quedan fuera.", "tipo": "Investigación", "tiempo": "3 semanas", "horas": 22, "etiquetas": ["Representación", "Decisiones"], "intencion": ["investigar"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Trabajo Social", "Sociología", "Psicología", "Educación", "Comunicaciones", "Antropología", "Ciencias Políticas", "Administración"], "problema": ["En muchos grupos las decisiones las toman los que más hablan o los de más edad. Otras personas callan por timidez, por miedo o porque piensan que no se les tomará en cuenta. Eso empobrece las decisiones.", "Medir cómo se sienten distintos integrantes permite mejorar la forma de decidir."], "desarrollar": ["Con permiso de un grupo, como un salón, un club o un grupo de vecinos, aplica una encuesta anónima que pregunte qué tan escuchados se sienten, quién habla más y qué decisiones recientes sienten que no los consideraron. Observa una reunión con permiso.", "Compara respuestas por grupos, como antigüedad, edad o género si el grupo lo permite sin identificar a nadie, y propón cinco prácticas para equilibrar voces, como rondas de palabra y votos secretos."], "ampliaciones": [{"titulo": "Prácticas de facilitación", "aporta": "prueba una práctica en una reunión y mide cambios."}, {"titulo": "Voces en línea", "aporta": "analiza la participación en chats."}, {"titulo": "Decisiones representativas", "aporta": "propón cómo documentar quién participó en una decisión."}], "objetivos": ["Medir sensación de ser escuchado.", "Comparar entre grupos.", "Detectar voces excluidas.", "Proponer prácticas."], "habilidades": ["Diseño de encuestas.", "Observación.", "Análisis.", "Facilitación."], "herramientas": ["Un formulario en línea.", "Una guía de observación.", "Hoja de cálculo."], "lineamientos": ["Si entrevistas o encuestas a personas, que sea voluntario, anónimo y con consentimiento claro, sin recoger datos personales ni imágenes sin permiso.", "Trabaja con la comunidad y no sobre ella: devuelve los resultados a quienes participaron y evita presentar a un grupo como problema.", "Asegura que ninguna respuesta pueda identificarse con una persona."], "otroSector": "El mismo estudio sirve para equipos de trabajo o consejos estudiantiles."}$a33sld$::jsonb,43),
('como-se-distribuyen-las-tareas-de-cuidado-dentro-de-las-familias','sociedad',array['salud']::text[],'¿Cómo se distribuyen las tareas de cuidado dentro de las familias y cómo influyen los estereotipos de género?','Analiza con estadísticas públicas cómo se reparten las tareas del hogar y del cuidado entre hombres y mujeres, y qué papel juegan los estereotipos en esa distribución.','Investigación','3 a 4 semanas',24,array['Tareas de cuidado','Estereotipos de género']::text[],array['investigar']::text[],'publicos',NULL,'trabajo social sociologia psicologia educacion comunicaciones antropologia ciencias politicas administracion analisis de estadisticas. visualizacion. pensamiento critico. redaccion. estadisticas oficiales. hoja de calculo. un editor de graficos.',$a34sld${"id": "como-se-distribuyen-las-tareas-de-cuidado-dentro-de-las-familias", "area": "sociedad", "areas2": ["salud"], "titulo": "¿Cómo se distribuyen las tareas de cuidado dentro de las familias y cómo influyen los estereotipos de género?", "resumen": "Analiza con estadísticas públicas cómo se reparten las tareas del hogar y del cuidado entre hombres y mujeres, y qué papel juegan los estereotipos en esa distribución.", "tipo": "Investigación", "tiempo": "3 a 4 semanas", "horas": 24, "etiquetas": ["Tareas de cuidado", "Estereotipos de género"], "intencion": ["investigar"], "datos": "publicos", "datosTexto": "públicos: trabaja con informes, estadísticas y registros que publican instituciones y fuentes abiertas.", "carreras": ["Trabajo Social", "Sociología", "Psicología", "Educación", "Comunicaciones", "Antropología", "Ciencias Políticas", "Administración"], "problema": ["Cocinar, limpiar, cuidar a niños y a personas mayores es trabajo que sostiene a las familias, pero suele recaer más en las mujeres. Muchas veces se asume como algo natural, cuando responde a ideas heredadas sobre roles.", "Mostrar cómo se distribuyen estas tareas ayuda a reconocer su valor y a conversar sobre acuerdos más justos."], "desarrollar": ["Con encuestas oficiales de uso del tiempo y otras estadísticas públicas, compara las horas dedicadas a tareas de cuidado y del hogar por sexo, edad y situación. Organiza los datos en tablas y gráficos.", "Describe las diferencias principales, relaciona los datos con estereotipos de género con apoyo de fuentes y propón preguntas para conversar en grupos sobre el reparto de tareas, sin juzgar a las familias."], "ampliaciones": [{"titulo": "Tu hogar", "aporta": "registra de forma privada cómo se reparten tareas en tu casa."}, {"titulo": "Cuánto vale este trabajo", "aporta": "estima el valor económico del trabajo doméstico."}, {"titulo": "Cambios entre generaciones", "aporta": "compara con datos de décadas anteriores."}], "objetivos": ["Reunir datos de uso del tiempo.", "Comparar el reparto de tareas.", "Relacionar con estereotipos.", "Plantear preguntas para el diálogo."], "habilidades": ["Análisis de estadísticas.", "Visualización.", "Pensamiento crítico.", "Redacción."], "herramientas": ["Estadísticas oficiales.", "Hoja de cálculo.", "Un editor de gráficos."], "lineamientos": ["Cita las fuentes que uses para respaldar lo que afirmas sobre cómo se aprende, y distingue entre lo que muestra la evidencia y lo que es tu opinión.", "Trata el tema con respeto: usa casos inventados o anónimos, sin datos que identifiquen a nadie, y si alguien necesita ayuda urgente remítelo a los servicios oficiales de atención, sin dar consejos psicológicos ni legales.", "No pidas a nadie datos íntimos de su hogar: usa datos públicos o solo tu propio registro, si decides hacerlo."], "otroSector": "El mismo análisis sirve para estudiar la distribución del trabajo no remunerado en cualquier sector."}$a34sld$::jsonb,44),
('que-dificultades-enfrentan-las-personas-que-cuidan-a-familiares','sociedad',array['salud','educacion']::text[],'¿Qué dificultades enfrentan las personas que cuidan a familiares y también deben estudiar o trabajar?','Estudia qué desafíos enfrentan quienes cuidan a un familiar mientras estudian o trabajan, y qué apoyos, flexibilidad y redes les serían útiles, usando fuentes públicas y testimonios anónimos.','Investigación','3 semanas',22,array['Cuidadores','Estudiar y trabajar']::text[],array['investigar','resolver']::text[],'publicos',NULL,'trabajo social sociologia psicologia educacion comunicaciones antropologia ciencias politicas administracion investigacion. escucha activa. sintesis. propuestas de mejora. estadisticas oficiales. una guia de conversacion. un editor de documentos.',$a35sld${"id": "que-dificultades-enfrentan-las-personas-que-cuidan-a-familiares", "area": "sociedad", "areas2": ["salud", "educacion"], "titulo": "¿Qué dificultades enfrentan las personas que cuidan a familiares y también deben estudiar o trabajar?", "resumen": "Estudia qué desafíos enfrentan quienes cuidan a un familiar mientras estudian o trabajan, y qué apoyos, flexibilidad y redes les serían útiles, usando fuentes públicas y testimonios anónimos.", "tipo": "Investigación", "tiempo": "3 semanas", "horas": 22, "etiquetas": ["Cuidadores", "Estudiar y trabajar"], "intencion": ["investigar", "resolver"], "datos": "publicos", "datosTexto": "públicos: trabaja con informes, estadísticas y registros que publican instituciones y fuentes abiertas.", "carreras": ["Trabajo Social", "Sociología", "Psicología", "Educación", "Comunicaciones", "Antropología", "Ciencias Políticas", "Administración"], "problema": ["Hay jóvenes y adultos que cuidan a hijos, hermanos o familiares mayores y a la vez estudian o trabajan. Esa doble carga rara vez se ve en las instituciones, y quienes la llevan suelen sentirse solos.", "Hacer visible su situación permite pensar apoyos realistas."], "desarrollar": ["Con fuentes oficiales y estudios, reúne información sobre cuántas personas combinan cuidado con estudio o trabajo y qué dificultades reportan. Complementa con tres a cinco testimonios anónimos y voluntarios, sin detalles personales.", "Agrupa las dificultades, como tiempo, cansancio, horarios o falta de apoyo, y diseña una propuesta de medidas posibles, como flexibilidad de entregas, redes de apoyo entre pares y guías de organización."], "ampliaciones": [{"titulo": "Guía de organización", "aporta": "crea una guía práctica para organizar el tiempo."}, {"titulo": "Redes de apoyo", "aporta": "propón un grupo de apoyo entre pares."}, {"titulo": "Diálogo con la institución", "aporta": "prepara cómo pedir flexibilidad con argumentos."}], "objetivos": ["Reunir información pública.", "Recoger testimonios anónimos.", "Agrupar dificultades.", "Proponer apoyos."], "habilidades": ["Investigación.", "Escucha activa.", "Síntesis.", "Propuestas de mejora."], "herramientas": ["Estadísticas oficiales.", "Una guía de conversación.", "Un editor de documentos."], "lineamientos": ["Trata el tema con respeto: usa casos inventados o anónimos, sin datos que identifiquen a nadie, y si alguien necesita ayuda urgente remítelo a los servicios oficiales de atención, sin dar consejos psicológicos ni legales.", "Si entrevistas o encuestas a personas, que sea voluntario, anónimo y con consentimiento claro, sin recoger datos personales ni imágenes sin permiso.", "No incluyas detalles que permitan identificar a la persona ni a la persona cuidada."], "otroSector": "El mismo estudio sirve para diseñar políticas de flexibilidad en empresas."}$a35sld$::jsonb,45),
('que-factores-dificultan-que-las-personas-denuncien-situaciones-d','sociedad',array['derecho']::text[],'¿Qué factores dificultan que las personas denuncien situaciones de discriminación o maltrato?','Revisa qué factores, como miedo, desconfianza, desconocimiento o falta de pruebas, hacen que muchas personas no denuncien discriminación o maltrato, y qué cambios facilitarían pedir ayuda, con enfoque informativo y respetuoso.','Investigación','3 a 4 semanas',24,array['Denuncia','Discriminación']::text[],array['investigar']::text[],'publicos',NULL,'trabajo social sociologia psicologia educacion comunicaciones antropologia ciencias politicas administracion lectura de fuentes. analisis critico. redaccion sensible. empatia. fuentes oficiales. un editor de documentos. un esquema visual.',$a36sld${"id": "que-factores-dificultan-que-las-personas-denuncien-situaciones-d", "area": "sociedad", "areas2": ["derecho"], "titulo": "¿Qué factores dificultan que las personas denuncien situaciones de discriminación o maltrato?", "resumen": "Revisa qué factores, como miedo, desconfianza, desconocimiento o falta de pruebas, hacen que muchas personas no denuncien discriminación o maltrato, y qué cambios facilitarían pedir ayuda, con enfoque informativo y respetuoso.", "tipo": "Investigación", "tiempo": "3 a 4 semanas", "horas": 24, "etiquetas": ["Denuncia", "Discriminación"], "intencion": ["investigar"], "datos": "publicos", "datosTexto": "públicos: trabaja con informes, estadísticas y registros que publican instituciones y fuentes abiertas.", "carreras": ["Trabajo Social", "Sociología", "Psicología", "Educación", "Comunicaciones", "Antropología", "Ciencias Políticas", "Administración"], "problema": ["Muchas situaciones de discriminación o maltrato no se denuncian: por miedo a represalias, por vergüenza, por no saber a dónde acudir o por pensar que no pasará nada. Esto deja a las personas sin protección y hace invisible el problema.", "Entender las barreras permite pensar cómo hacer los canales de ayuda más accesibles."], "desarrollar": ["Con fuentes oficiales y estudios de organizaciones reconocidas, resume qué factores se identifican como barreras para denunciar y qué canales de ayuda existen. No uses casos reales ni preguntes a personas por sus experiencias.", "Elabora un esquema de barreras y de posibles mejoras, como información clara, atención amable y confidencialidad, y una guía informativa que oriente a servicios oficiales de atención, sin dar consejos legales ni psicológicos."], "ampliaciones": [{"titulo": "Cómo acompañar", "aporta": "elabora una guía para apoyar a alguien que cuenta una situación."}, {"titulo": "Canales institucionales", "aporta": "revisa qué tan claros son los canales de una institución."}, {"titulo": "Lenguaje que no revictimiza", "aporta": "analiza cómo hablar sin culpar a quien denuncia."}], "objetivos": ["Reunir evidencia de barreras.", "Identificar canales de ayuda.", "Proponer mejoras.", "Elaborar una guía informativa."], "habilidades": ["Lectura de fuentes.", "Análisis crítico.", "Redacción sensible.", "Empatía."], "herramientas": ["Fuentes oficiales.", "Un editor de documentos.", "Un esquema visual."], "lineamientos": ["Trata el tema con respeto: usa casos inventados o anónimos, sin datos que identifiquen a nadie, y si alguien necesita ayuda urgente remítelo a los servicios oficiales de atención, sin dar consejos psicológicos ni legales.", "Cita las fuentes que uses para respaldar lo que afirmas sobre cómo se aprende, y distingue entre lo que muestra la evidencia y lo que es tu opinión.", "No busques ni publiques experiencias personales y remite siempre a los servicios oficiales de atención."], "otroSector": "El mismo análisis sirve para evaluar canales de denuncia en empresas o instituciones."}$a36sld$::jsonb,46)
